import { useEffect, useState } from "react";
import { api } from "../../api/index";

export default function AdminPage() {
  const [users, setUsers] = useState([]);

  const loadUsers = async () => {
    const { data } = await api.apiClient.get("/api/admin/users");
    setUsers(data);
  };

  useEffect(() => {
    loadUsers();
  }, []);

  const changeRole = async (id, role) => {
    await api.apiClient.patch(`/api/admin/users/${id}`, { role });
    loadUsers();
  };

  const deleteUser = async (id) => {
    await api.apiClient.delete(`/api/admin/users/${id}`);
    loadUsers();
  };

  return (
    <div style={{ padding: 40 }}>
      <h2>Админ панель</h2>

      {users.map((u) => (
        <div key={u.id} style={{ marginBottom: 10 }}>
          {u.email} — {u.role}

          <button onClick={() => changeRole(u.id, "admin")}>
            Сделать admin
          </button>

          <button onClick={() => changeRole(u.id, "user")}>
            Сделать user
          </button>

          <button onClick={() => deleteUser(u.id)}>Удалить</button>
        </div>
      ))}
    </div>
  );
}
